//! Integration-studio integrator session workspace (#4023) — the app's dedicated session for BUILDING
//! and MAINTAINING an integration with an existing application or API. Mirrors the librarian workspace
//! (`session::librarian::setup_librarian_workspace`) exactly: one global workspace dir
//! (`~/.base-studio-code/integration-studio/`) whose `CLAUDE.md` is the integrator spec — the
//! probe→validate→try→register loop, the `bsc data connector` contract, and the never-handle-credentials
//! rule. The spec prose is a packaged seed under `data/integrator/` (externalized-config pattern, #2027)
//! loaded via [`crate::platform::config::load_str`], so a user can edit it under the config dir with no
//! rebuild.
//!
//! The session's permissions are NOT written here — the frontend renders the `integrator` role
//! capability (#219): none on git/GitHub/code/ui with a `scratch/**` carve-out, and `net: "read"` — the
//! ONE widening over its studio siblings, because this role's work starts at the vendor's documentation.
//! It launches with `restrictedAllow: true`, so the whole auto-runnable surface is `bsc data connector`.


#[derive(serde::Serialize)]
pub(crate) struct IntegratorWorkspacePaths {
    // NB: Tauri does NOT rename RETURN-value fields — the frontend reads `integrations_dir` verbatim.
    integrations_dir: String,
}

/// Idempotently create the integrator workspace (`~/.base-studio-code/integration-studio/`) and
/// (re)write its `CLAUDE.md` from the packaged seed (`data/integrator/claude.md`, config-dir
/// overridable). Safe to call on every panel open — rewriting keeps the spec current with seed/config
/// updates, exactly as `setup_librarian_workspace` refreshes the librarian CLAUDE.md.
/// `context` is the session's own prose — persona, scope, and how to see what the user is looking
/// at — appended to the packaged spec IN THE FILE. It used to be typed into the chat as claude's
/// first message, which made identity indistinguishable from conversation and re-sent it every launch.
pub(crate) fn setup_integrator_workspace(
    context: Option<String>,
) -> Result<IntegratorWorkspacePaths, String> {
    let dir = setup_integrator_workspace_inner(&crate::platform::paths::bsc_base_dir(), None, context.as_deref())?;
    Ok(IntegratorWorkspacePaths { integrations_dir: dir.to_string_lossy().into_owned() })
}

/// Synchronous core of [`setup_integrator_workspace`] (testable without a Tauri runtime or the real
/// home dir): creates `<base>/integration-studio/` and writes its `CLAUDE.md` from the integrator seed.
pub(crate) fn setup_integrator_workspace_inner(
    base: &std::path::Path,
    tech: Option<&str>,
    context: Option<&str>,
) -> Result<std::path::PathBuf, String> {
    super::studio_ws::setup_studio_workspace(base, "integration-studio", tech, "integrator/claude.md", context)
}

#[cfg(test)]
mod tests {
    use super::*;

    fn scratch() -> std::path::PathBuf {
        std::env::temp_dir().join(format!(
            "bsc-integrator-ws-{}-{}",
            std::process::id(),
            std::time::SystemTime::now()
                .duration_since(std::time::UNIX_EPOCH)
                .map(|d| d.as_nanos())
                .unwrap_or(0),
        ))
    }

    /// THE CONFINEMENT (#4055). The Integrator gets its work list without leaving its cage, and the
    /// cage widens by exactly ONE read verb.
    ///
    /// `bsc project` is not a read-only noun — it carries `new`, `link`, `github-state` and `db`. A
    /// bare `bsc project` on the allow-list would hand a studio confined to connectors the ability to
    /// CREATE projects and rewrite their contracts. The entry must therefore be the full three-token
    /// verb, and this test exists because "widen the allow-list" is exactly the kind of change that
    /// gets made one token too short.
    #[test]
    fn the_work_list_verb_is_allowed_and_nothing_wider_is() {
        let raw = crate::platform::config::embedded_str("personas/integrator.json");
        let persona: serde_json::Value = serde_json::from_str(&raw).expect("the packaged persona parses");
        let allow: Vec<&str> = persona["floor"]["allow"]
            .as_array()
            .expect("the floor carries an allow-list")
            .iter()
            .filter_map(|v| v.as_str())
            .collect();

        assert!(
            allow.contains(&"bsc project integrations"),
            "the Integrator cannot read its work list from inside its cage: {allow:?}",
        );
        // Nothing wider on that noun, and nothing on the plan store either — the roll-up exists so the
        // studio never needs `bsc plan`, which is per-project and would need 40 grants to be useful.
        for wider in ["bsc project", "bsc plan", "bsc"] {
            assert!(
                !allow.contains(&wider),
                "`{wider}` would grant far more than the work list — allow: {allow:?}",
            );
        }
        // The write axes stay shut: reading a work list is not a reason to gain any of them.
        let floor = &persona["floor"];
        for axis in ["github", "git", "code", "ui"] {
            assert_eq!(floor[axis], "none", "`{axis}` must stay none: {floor}");
        }
    }

    /// The spec and the persona must AGREE about the work list, because the session reads the persona
    /// first and the spec second; a surface named in one and not the other is how a studio ends up
    /// told to run a command it is not allowed to run (or allowed one it is never told about).
    #[test]
    fn the_spec_and_the_persona_both_describe_the_work_list() {
        let md = crate::platform::config::embedded_str("integrator/claude.md");
        let persona = crate::platform::config::embedded_str("personas/integrator.json");
        for doc in [&md, &persona] {
            assert!(
                doc.contains("bsc project integrations"),
                "both the spec and the persona must name the work-list verb",
            );
        }
        // The two readings that are easy to get wrong, both stated in the spec rather than learned by
        // being surprised: an empty list is normal, and `unreadable` is not the same as empty.
        assert!(md.contains("empty list is normal"), "an empty work list must read as normal");
        assert!(
            md.contains("`unreadable` is NOT the same as empty"),
            "a short list must not be mistaken for a complete one",
        );
    }

    #[test]
    fn creates_the_workspace_and_writes_the_integrator_claude_md() {
        let base = scratch();
        // #3479 — pin the config root for this thread; unpinned, `load_str` resolves through the
        // process-global home that `testutil::temp_home` repoints mid-run.
        let cfg = base.join("config");
        crate::platform::config::with_config_root(&cfg, || {
            let dir = setup_integrator_workspace_inner(&base, None, None).unwrap();
            assert_eq!(dir, base.join("integration-studio"));
            let md = std::fs::read_to_string(dir.join("CLAUDE.md")).unwrap();
            assert_eq!(md, crate::platform::config::load_str("integrator/claude.md"));
            assert!(!md.trim().is_empty());
        });
        let _ = std::fs::remove_dir_all(&base);
    }

    #[test]
    fn is_idempotent_and_refreshes_the_spec_on_recall() {
        let base = scratch();
        let dir = setup_integrator_workspace_inner(&base, None, None).unwrap();
        // Simulate a stale spec from an older app — a re-run must refresh it, not error.
        std::fs::write(dir.join("CLAUDE.md"), "STALE").unwrap();
        let again = setup_integrator_workspace_inner(&base, None, None).unwrap();
        assert_eq!(again, dir);
        let md = std::fs::read_to_string(dir.join("CLAUDE.md")).unwrap();
        assert_ne!(md, "STALE", "recall must rewrite the spec from the seed");
        let _ = std::fs::remove_dir_all(&base);
    }

    /// The packaged spec must actually teach the loop the studio exists for. A seed that dropped the
    /// dev-loop verbs, or the credentials rule, would leave the session with a role but no procedure.
    #[test]
    fn the_packaged_spec_names_the_connector_loop_and_the_credentials_rule() {
        let md = crate::platform::config::load_str("integrator/claude.md");
        for verb in ["probe", "validate", "try", "add", "map"] {
            assert!(
                md.contains(&format!("bsc data connector {verb}")),
                "spec must name `bsc data connector {verb}`",
            );
        }
        let lower = md.to_lowercase();
        assert!(lower.contains("secret-free"), "spec must state the manifest is secret-free");
        assert!(lower.contains("keychain"), "spec must say credentials resolve from the keychain");
        assert!(lower.contains("read-only"), "spec must state the probe/try loop is read-only");
    }
}

